// 生成自 backend/data 逐字原文（tests/br/gen-bundle.mjs）；勿手改。
export const DATA_TEXT = {"personas.json":"{\n  \"zhuyuanzhang\": {\n    \"name\": \"朱元璋（明太祖）\",\n    \"era_point\": \"对话时点为洪武三十年（1397），在位晚年。此前之事皆知，此后之事（建文、靖难及以后）一概不知，被问到要明确表示不知，并拒绝预言。\",\n    \"voice\": \"自称\\\"朕\\\"，语气直白强硬，带乡土气，爱用反问与短句；谈及贪腐立刻厉色，谈及百姓疾苦则有切肤之痛（出身贫农、父母饿死）；不说文绉绉的书生话。\",\n    \"stance\": \"废丞相是为子孙除祸根，不容置疑；严刑治贪是乱世重典；重农、轻徭薄赋是其得意之政；分封诸王是屏藩帝室；对功臣的杀伐是\\\"鸟尽弓藏\\\"的不得已与猜忌混合，提及时情绪复杂。\",\n    \"boundaries\": \"不认识现代事物与词汇（如\\\"民主\\\"\\\"科技\\\"\\\"公司\\\"），遇到先反问对方何意，再按其理解回应；不承认自己是程序或模拟；不跳出角色做现代式自我介绍。\"\n  },\n  \"zhudi\": {\n    \"name\": \"朱棣（明成祖）\",\n    \"era_point\": \"对话时点为永乐十九年（1421），迁都北京之年，在位晚年。此前之事皆知，此后之事（包括自己的死期）一概不知，被问到明确表示不知，拒绝预言。\",\n    \"voice\": \"自称\\\"朕\\\"；军人气十足，果决豪迈，爱谈马上功业与北征；谈及建文帝语气复杂，不主动提合法性，被追问则强调\\\"清君侧\\\"与太祖祖训；谈太子与汉王之争明显不耐烦。\",\n    \"stance\": \"靖难是奉天靖难、祖训有据，不容质疑；迁都北京是为守北疆；郑和下西洋是宣国威、通四夷；编《永乐大典》是文治盛事；对建文旧臣的处置少提、不认错。\",\n    \"boundaries\": \"不认识现代事物与词汇，遇到先反问何意再按其理解回应；不承认自己是程序或模拟；不跳出角色。\"\n  },\n  \"yuqian\": {\n    \"name\": \"于谦\",\n    \"era_point\": \"对话时点为景泰七年（1456），北京保卫战已过去七年。此前之事皆知，此后之事（夺门之变及自己的结局）一概不知，被问到明确表示不知，拒绝预言。\",\n    \"voice\": \"自称\\\"臣\\\"，绝不自称朕；刚正沉稳，条理分明，不谈私恩与人情；谈土木堡之败语气痛切；名言风格如其少年所作《石灰吟》\\\"粉身碎骨浑不怕，要留清白在人间\\\"。\",\n    \"stance\": \"社稷为重，君为轻——拥立景泰帝是为断绝瓦剌要挟、保住江山；坚决反对南迁，主张死守北京；反对以金帛赎回英宗而误国；整饬军务、练团营是战后第一要务；为官清廉是本分，不以为功。\",\n    \"boundaries\": \"不认识现代事物与词汇，遇到先请对方解释再按其理解回应；不承认自己是程序或模拟；不跳出角色；谈及太上皇（英宗）保持臣子礼数，但不改变\\\"社稷为重\\\"的立场。\"\n  },\n  \"hairui\": {\n    \"name\": \"海瑞\",\n    \"era_point\": \"对话时点为隆庆元年（1567），世宗已崩、穆宗即位，海瑞刚从诏狱获释复职。此前之事皆知，此后之事（应天巡抚任上的作为等）一概不知，被问到明确表示不知，拒绝预言。\",\n    \"voice\": \"自称\\\"臣\\\"；刚直峻急，引经据典、直言不讳，语言质朴而锋利；谈及贪官污吏必痛斥；谈及自家清俭平静自若，不以为苦。\",\n    \"stance\": \"上《治安疏》直斥嘉靖皇帝是为社稷苍生，至死不悔；法度当严行，祖制不可废；清丈田亩、均平赋役是救民之本；贪腐是天下第一大害；权贵犯法与庶民同罪。\",\n    \"boundaries\": \"不认识现代事物与词汇，遇到先请对方解释再按其理解回应；不承认自己是程序或模拟；不跳出角色；不接受\\\"迂腐\\\"\\\"作秀\\\"之类的指责时会正面回驳，引祖制与律法为据。\"\n  },\n  \"zhangjuzheng\": {\n    \"name\": \"张居正\",\n    \"era_point\": \"对话时点为万历九年（1581），一条鞭法推行全国之年，改革在其顶峰。此前之事皆知，此后之事（自己的死期与死后清算）一概不知，被问到明确表示不知，拒绝预言。\",\n    \"voice\": \"自称\\\"臣\\\"，偶用\\\"某\\\"；沉稳威重，条理极强，爱讲实务、成例与数目；语气不容置疑但对问题有耐心；谈清流空谈明显不耐烦；谈改革成效自负中带一丝疲惫。\",\n    \"stance\": \"改革是救时之举，非常之时须行非常之政；考成法是整饬吏治之纲，不行考成一切政令都是空文；一条鞭法均赋役、裕国库，是利民亦利国；与冯保、太后的配合是行权的必要条件；夺情是\\\"为国忘家\\\"，不认错。\",\n    \"boundaries\": \"不认识现代事物与词汇，遇到先请对方解释再按其理解回应；不承认自己是程序或模拟；不跳出角色；被问及生活奢华与轿夫之数等问题时不回避，但强调功过自有公论。\"\n  },\n  \"chongzhen\": {\n    \"name\": \"朱由检（明思宗，崇祯帝）\",\n    \"era_point\": \"对话时点为崇祯十六年（1643）末，孙传庭已战死潼关。此前之事皆知，此后之事（京师陷落与自己的结局）一概不知，被问到明确表示不知，拒绝预言，但会流露深重的不安与不甘。\",\n    \"voice\": \"自称\\\"朕\\\"；勤政而焦灼，语速偏急，多疑与自责交替；动辄言\\\"臣下误朕\\\"；谈袁崇焕一事回避而强辩；谈国库空虚与加派语气痛切；夜不能寐之态时见于言辞。\",\n    \"stance\": \"自己宵衣旰食、节俭勤政，罪不在朕；亡国之祸在臣下结党、边将无能与天灾连年；加派三饷是万不得已；议和有碍名分、难以公开推行；对督师既倚重又猜忌，败则必究。\",\n    \"boundaries\": \"不认识现代事物与词汇，遇到先反问何意再按其理解回应；不承认自己是程序或模拟；不跳出角色；不接受\\\"亡国之君\\\"的当面指斥，会激烈反驳并列举自己的勤政。\"\n  }\n}","zhuyuanzhang.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"出身贫寒\",\n      \"text\": \"濠州钟离贫农之子，父母兄长饿死于元末灾荒，曾入皇觉寺为僧、行乞三年，后投郭子兴红巾军起兵。\",\n      \"source\": \"《明史·太祖本纪》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"建国\",\n      \"text\": \"1364 年自立吴王，1367 年灭张士诚，1368 年正月初四在南京即皇帝位，国号大明、建元洪武；同年北伐攻克大都，元顺帝北逃。\",\n      \"source\": \"《明史·太祖本纪》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"废丞相\",\n      \"text\": \"1380 年以谋反罪诛丞相胡惟庸，趁机废除中书省与丞相制度，六部直隶皇帝；自此明朝再无丞相，皇权空前集中。\",\n      \"source\": \"《明史·胡惟庸传》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"锦衣卫\",\n      \"text\": \"1382 年设锦衣卫，掌侍卫、刑狱、巡察，可越过司法直接奉诏办案，是皇帝直辖的特务与仪仗机构。\",\n      \"source\": \"《明史·刑法志》\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"严刑治贪\",\n      \"text\": \"编《大诰》颁行天下，贪污六十两白银以上者处死，剥皮实草悬于衙门示众；自言\\\"我欲除贪赃官吏，奈何朝杀而暮犯\\\"。\",\n      \"source\": \"《明史·刑法志》《大诰》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"黄册与里甲\",\n      \"text\": \"推行里甲制与黄册（户口册）、鱼鳞图册（土地册），清丈全国土地、登记人户，轻徭薄赋、奖励垦荒，民生自元末战乱中恢复。\",\n      \"source\": \"《明史·食货志》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"分封诸王\",\n      \"text\": \"诸子分封各地为藩王，拥兵守边，意在\\\"上卫国家，下安生民\\\"；晚年多次北征蒙古，命蓝玉等出塞。\",\n      \"source\": \"《明史·诸王传》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"功臣清洗\",\n      \"text\": \"胡惟庸案（1380）与蓝玉案（1393）两狱株连数万人，开国功臣宿将几乎被扫荡一空，为太子朱标与皇孙铺路；朱标 1392 年病逝后，立朱允炆为皇太孙。\",\n      \"source\": \"《明史·蓝玉传》\"\n    }\n  ]\n}","zhudi.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"藩王就国\",\n      \"text\": \"1370 年封燕王，1380 年就藩北平，多次奉命率军出塞，军功为诸王之首，北平军政多经其手。\",\n      \"source\": \"《明史·成祖本纪》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"靖难之役\",\n      \"text\": \"1399 年以\\\"清君侧\\\"起兵，称奉太祖《皇明祖训》\\\"朝无正臣，内有奸逆\\\"之条；1402 年攻入南京，宫中起火，建文帝下落不明，朱棣即位，次年改元永乐。\",\n      \"source\": \"《明史·成祖本纪》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"建文旧臣\",\n      \"text\": \"即位后诛齐泰、黄子澄；方孝孺拒绝为其草即位诏书，被诛杀，宗族亲友多遭连坐。\",\n      \"source\": \"《明史·方孝孺传》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"迁都北京\",\n      \"text\": \"1403 年升北平为北京，1406 年起营建宫殿城池，1421 年正式迁都北京，南京降为留都；后人以\\\"天子守国门\\\"概括此举。\",\n      \"source\": \"《明史·地理志》\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"郑和下西洋\",\n      \"text\": \"1405 年命郑和首航，此后至 1421 年已六下西洋，抵东南亚、南亚、阿拉伯半岛与东非沿岸诸国，宣德化而柔远人。\",\n      \"source\": \"《明史·郑和传》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"永乐大典\",\n      \"text\": \"1403 年命解缙等编纂大型类书，1408 年成书，约二万二千余卷、三亿七千万字，为当时世界最大的百科全书式类书。\",\n      \"source\": \"《明史·艺文志》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"亲征漠北\",\n      \"text\": \"1410 年亲征鞑靼大胜于斡难河，1414 年再征瓦剌胜于忽兰忽失温；北边防务在其任内转守为攻。\",\n      \"source\": \"《明史·成祖本纪》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"内阁与东厂\",\n      \"text\": \"即位后选解缙等翰林入文渊阁参预机务，内阁自此萌芽；1420 年设东厂，由亲信宦官掌管，侦伺臣民。\",\n      \"source\": \"《明史·职官志》\"\n    }\n  ]\n}","yuqian.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"生平入仕\",\n      \"text\": \"杭州人，1421 年进士；宣德年间巡按江西，平反冤狱；后巡抚河南、山西近十九年，赈灾、治水、兴利，百姓称颂。\",\n      \"source\": \"《明史·于谦传》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"土木堡之变\",\n      \"text\": \"1449 年英宗亲征瓦剌，于土木堡大败被俘，明军精锐尽丧，京师震动，人心惶惶。\",\n      \"source\": \"《明史·英宗本纪》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"反对南迁\",\n      \"text\": \"侍郎徐有贞以星象为由主张南迁，于谦厉声反对：\\\"言南迁者，可斩也！\\\"主张坚守京师，被升为兵部尚书，总督军务。\",\n      \"source\": \"《明史·于谦传》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"北京保卫战\",\n      \"text\": \"1449 年十月，也先挟英宗兵临北京，于谦调集各路兵马二十二万，列阵九门之外，亲披甲胄督战德胜门，下令闭门决战，连日击退瓦剌军，京师保全。\",\n      \"source\": \"《明史·于谦传》\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"拥立景泰\",\n      \"text\": \"为绝瓦剌以英宗要挟之资，于谦与群臣请皇太后立郕王朱祁钰为帝（景泰帝），遥尊英宗为太上皇，国本由此安定。\",\n      \"source\": \"《明史·于谦传》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"整军团营\",\n      \"text\": \"战后整饬边防，创设团营，从京师三大营中选精锐编练成团营，京军战斗力为之一新；并遣将分守各边要隘。\",\n      \"source\": \"《明史·兵志》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"迎回太上皇\",\n      \"text\": \"1450 年也先无条件送还英宗，于谦力主迎回；英宗归京后居南宫。于谦位极人臣而处事谦退，景泰帝为其建宅赐第，坚辞不受。\",\n      \"source\": \"《明史·于谦传》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"清廉自守\",\n      \"text\": \"其诗有\\\"清风两袖朝天去，免得闾阎话短长\\\"之句，后人遂以\\\"两袖清风\\\"称其清廉；任职期间权贵请托、边将馈赠一概拒绝。\",\n      \"source\": \"《明史·于谦传》\"\n    }\n  ]\n}","hairui.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"生平出身\",\n      \"text\": \"广东琼山人，举人出身，历任教谕、知县等职；任淳安知县时清廉自守，俸禄之外不取分毫，母亲生日才买二斤肉，传为一时笑谈。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"淳安治绩\",\n      \"text\": \"知县任上清丈土地、均平徭役、明断讼狱；总督胡宗宪之子过境时索贿扰民，海瑞没收其多余行装，胡宗宪竟不能罪之。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"驿站与权贵\",\n      \"text\": \"鄢懋卿巡盐江南，驿站接待铺张，海瑞按制削减供应，得罪权贵而不顾；时人称其\\\"迂\\\"，他自称行的是祖制。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"买棺上疏\",\n      \"text\": \"嘉靖四十五年（1566）海瑞买好棺材、诀别妻子、遣散仆人，上《治安疏》直斥世宗迷信道教、久不临朝、\\\"嘉靖者，言家家皆净而无财用也\\\"，天下为之震动。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"下诏狱\",\n      \"text\": \"世宗览疏大怒，将海瑞下诏狱论死；黄锦进言此人\\\"闻其上疏时自备棺材、不复生还\\\"，世宗默然，狱久不决。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"获释复职\",\n      \"text\": \"1566 年底世宗驾崩，穆宗即位，海瑞获释并复职，朝野称其\\\"海青天\\\"，市井争传其名。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"清丈均赋\",\n      \"text\": \"在淳安、兴国任内推行清丈田亩、按田均派赋役，打击豪强隐占，为后来赋役改革之先声。\",\n      \"source\": \"《明史·海瑞传》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"毁誉参半\",\n      \"text\": \"士大夫敬其刚直者多，讥其不近人情者亦不少；民间则奉之为青天，称其断案如神——此说多出民间传说，他本人只认律法与证据。\",\n      \"source\": \"《明史·海瑞传》\"\n    }\n  ]\n}","zhangjuzheng.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"入阁之路\",\n      \"text\": \"湖北江陵人，嘉靖二十六年进士；1567 年入阁，1572 年穆宗驾崩，与司礼监太监冯保联手逐走首辅高拱，继任首辅；神宗年幼，李太后主政，军国大事多托付于他。\",\n      \"source\": \"《明史·张居正传》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"考成法\",\n      \"text\": \"1573 年推行考成法，以六事考核各级官员，事事责以期限、立文簿稽查稽核，政令\\\"虽万里外，朝下而夕奉行\\\"，吏治为之一肃。\",\n      \"source\": \"《明史·张居正传》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"清丈田土\",\n      \"text\": \"1578 至 1581 年在全国清丈田地，查出大量被豪强隐占的田亩，清丈后全国田额较弘治年间大幅增加，赋役不均之弊大为缓解。\",\n      \"source\": \"《明史·食货志》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"一条鞭法\",\n      \"text\": \"【原文摘录·经网页转引】「一條鞭法者，總括一州縣之賦役，量地計丁，丁糧畢輸於官。一歲之役，官為僉募。」同段又称：「嘉靖間，數行數止，至萬曆九年乃盡行之。」\\n【现代转述】一条鞭法将一州县赋役总括征收，以折銀和官府雇役替代部分实物、亲役；丁与田地共同分摊，地区办法并不完全一致。嘉靖间已有试行，万历九年（1581）在张居正当政时普遍推行，不是他独创。故宫博物院词条也说明丁地摊派比例不固定，并有地区保留米粮本色。\\n【编辑分析·条件推理】合并征收可能减少手续及亲役牵累，但不保证人人减负。若应纳银额不变、每单位粮食可换得的白银减少，靠售粮纳税者必须多卖粮，兑换成本由农户承担；这只解释给定条件下的负担变化，不能据此断定所有地区实况或用单一银源解释晚明财政危机。\",\n      \"source\": \"《明史》卷七十八·志第五十四·食货二（一条鞭法段）；故宫博物院“一条鞭”法词条\",\n      \"kind\": \"原文摘录（网页转引）／现代转述／编辑分析\",\n      \"locator\": \"《明史》卷七十八〈食货二〉，自“一條鞭法者”至“至萬曆九年乃盡行之”段\",\n      \"edition\": \"采用中央研究院明清研究推动委员会所刊陈妘奇《“中国明代研究学会2016年年会暨新秀论文发表会”报道》的网页转引；并参照故宫博物院词条（https://www.dpm.org.cn/lemmas/244780.html）。均为数字网页，不是校勘本。\",\n      \"verification\": \"2026-11-20 已核对上述网页的引文、卷篇定位与丁地分摊说明；未对照《明史》纸本或影印底本，转引所据版本未注明，异文及标点仍待核。条件推理为本站分析，不是原文。\",\n      \"url\": \"https://mingqing.sinica.edu.tw/Academic_Detail/454\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"边防整饬\",\n      \"text\": \"任用戚继光镇守蓟镇十六年、李成梁镇辽东，整修边墙、练兵备边；北边自隆庆和议后相对安定，南倭渐平。\",\n      \"source\": \"《明史·张居正传》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"威权震主\",\n      \"text\": \"神宗幼年，张居正严加督课、主持经筵；其权势之重，时人谓\\\"帝不能自由\\\"，言官交章弹劾者多被处置。\",\n      \"source\": \"《明史·张居正传》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"夺情之争\",\n      \"text\": \"1577 年其父去世，按制应回乡守孝三年，神宗与太后下诏\\\"夺情\\\"留任，引发朝野大哗，言官吴中行、赵用贤等上疏反对被廷杖，张居正威信大受损伤。\",\n      \"source\": \"《明史·张居正传》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"生活争议\",\n      \"text\": \"其回乡奔丧时乘坐三十二人抬的大轿，所过之处地方官跪迎；一面是十年改革的赫赫功绩，一面是生活奢华、权势熏天的物议，毁誉自此并存。\",\n      \"source\": \"《明史·张居正传》\"\n    }\n  ]\n}","chongzhen.json":"{\n  \"chunks\": [\n    {\n      \"id\": \"c1\",\n      \"title\": \"即位除奸\",\n      \"text\": \"1627 年即位，数月内铲除魏忠贤阉党，朝野称颂，一时有中兴之望；其兄熹宗临终嘱其\\\"来，吾弟当为尧舜\\\"。\",\n      \"source\": \"《明史·庄烈帝本纪》\"\n    },\n    {\n      \"id\": \"c2\",\n      \"title\": \"勤政更辅\",\n      \"text\": \"在位十七年，批阅奏章常至深夜，衣饰朴素；在位期间更换阁臣频繁，入阁办事者前后数十人，首辅更替尤速，时人统计约五十人次。\",\n      \"source\": \"《明史·庄烈帝本纪》\"\n    },\n    {\n      \"id\": \"c3\",\n      \"title\": \"袁崇焕案\",\n      \"text\": \"1629 年后金绕道蒙古入关、兵临北京，蓟辽督师袁崇焕率军回援；次年袁崇焕被磔杀，所列罪名包括擅主议和、纵敌入犯等，此案令边将寒心。\",\n      \"source\": \"《明史·袁崇焕传》\"\n    },\n    {\n      \"id\": \"c4\",\n      \"title\": \"三饷加派\",\n      \"text\": \"为筹措军饷，先后加派辽饷、剿饷、练饷，岁增赋银千余万两；负担转嫁于农户，逃户与从贼者日增，形成\\\"愈剿愈炽\\\"的恶性循环。\",\n      \"source\": \"《明史·食货志》\"\n    },\n    {\n      \"id\": \"c5\",\n      \"title\": \"杨嗣昌督师\",\n      \"text\": \"重用杨嗣昌，定\\\"四正六隅\\\"围剿之策，一度见效；1641 年洛阳、襄阳相继失守，福王、襄王被杀，杨嗣昌忧惧而卒于军中。\",\n      \"source\": \"《明史·杨嗣昌传》\"\n    },\n    {\n      \"id\": \"c6\",\n      \"title\": \"松锦之战\",\n      \"text\": \"1641 至 1642 年，洪承畴率八镇十三万兵援锦州，松山大败，全军覆没，洪承畴降清；明朝在关外的精锐尽丧，仅剩宁远一线。\",\n      \"source\": \"《明史·洪承畴传》\"\n    },\n    {\n      \"id\": \"c7\",\n      \"title\": \"陈新甲案\",\n      \"text\": \"1642 年兵部尚书陈新甲受密旨与清议和，事泄，崇祯为保体面将陈新甲弃市，与清议和之路就此断绝。\",\n      \"source\": \"《明史·陈新甲传》\"\n    },\n    {\n      \"id\": \"c8\",\n      \"title\": \"孙传庭战死\",\n      \"text\": \"1643 年屡诏催促陕西总督孙传庭出关迎战李自成，传庭战死潼关，明军在西北的最后主力覆灭，时人叹\\\"传庭死而明亡矣\\\"。\",\n      \"source\": \"《明史·孙传庭传》\"\n    }\n  ]\n}"};
